def test_hyb_mgga_xc_wb97m_v_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_wb97m_v", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.099222202154168e+00, -4.006337908983780e+00, -3.876355267693448e+00, -3.696714183252379e+00, -3.452985737916372e+00, -3.131329846120378e+00, -2.724277514295216e+00, -2.240684477992517e+00, -1.714696887783559e+00, -1.199544119407645e+00, -7.440040527681537e-01, -4.851148323348901e-01, -4.168407525366752e-01, -3.167012762565630e-01, -1.980225759116956e-01, -9.028307330463020e-02, -5.494611156262328e-02, -3.081542457357607e-02, -9.680281943141484e-03, -1.435104416018411e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


